<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Northline Supply Co. | Modern Retail Essentials</title>
  <style>
    :root {
      color-scheme: light;
      --ink: #141414;
      --muted: #686b72;
      --line: #e8e5df;
      --paper: #fbfaf7;
      --card: #ffffff;
      --charcoal: #23211f;
      --sage: #dce8d6;
      --sand: #efe4d2;
      --clay: #b96f51;
      --lime: #dff26d;
      --shadow: 0 24px 70px rgba(28, 26, 23, 0.12);
      --radius-xl: 34px;
      --radius-lg: 24px;
      --radius-md: 16px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(223, 242, 109, 0.28), transparent 30rem),
        linear-gradient(180deg, #fbfaf7 0%, #f5f0e8 100%);
      color: var(--ink);
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      border: 0;
      font: inherit;
      cursor: pointer;
    }

    .app {
      min-height: 100vh;
      overflow: hidden;
    }

    .container {
      width: min(1180px, calc(100% - 40px));
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(18px);
      background: rgba(251, 250, 247, 0.78);
      border-bottom: 1px solid rgba(232, 229, 223, 0.8);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 22px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      letter-spacing: -0.04em;
      font-size: 1.2rem;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border-radius: 14px;
      color: var(--paper);
      background: var(--charcoal);
      box-shadow: 0 10px 25px rgba(35, 33, 31, 0.18);
    }

    .nav-links {
      display: flex;
      gap: 26px;
      color: var(--muted);
      font-size: 0.95rem;
      font-weight: 650;
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-height: 44px;
      padding: 0 18px;
      border-radius: 999px;
      font-weight: 750;
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    .pill:hover {
      transform: translateY(-2px);
    }

    .pill-dark {
      background: var(--charcoal);
      color: white;
      box-shadow: 0 16px 35px rgba(35, 33, 31, 0.18);
    }

    .pill-light {
      background: white;
      color: var(--charcoal);
      border: 1px solid var(--line);
    }

    .hero {
      padding: 54px 0 34px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(340px, 0.82fr);
      gap: 28px;
      align-items: stretch;
    }

    .hero-copy {
      position: relative;
      min-height: 610px;
      padding: 58px;
      border-radius: var(--radius-xl);
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.74), rgba(255, 255, 255, 0.36)),
        var(--sand);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero-copy::after {
      content: "";
      position: absolute;
      width: 360px;
      height: 360px;
      right: -90px;
      bottom: -100px;
      border-radius: 50%;
      background: rgba(220, 232, 214, 0.8);
      filter: blur(4px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      width: fit-content;
      margin: 0 0 22px;
      padding: 8px 12px;
      border: 1px solid rgba(35, 33, 31, 0.1);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.58);
      color: #5d5a54;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--clay);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      position: relative;
      z-index: 1;
      max-width: 780px;
      margin-bottom: 22px;
      font-size: clamp(3.2rem, 8vw, 7.35rem);
      line-height: 0.9;
      letter-spacing: -0.09em;
    }

    .hero-copy > p {
      position: relative;
      z-index: 1;
      max-width: 550px;
      margin-bottom: 34px;
      color: #54504a;
      font-size: clamp(1.04rem, 2vw, 1.25rem);
      line-height: 1.65;
    }

    .hero-actions {
      position: relative;
      z-index: 1;
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-bottom: 56px;
    }

    .hero-stats {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      max-width: 640px;
    }

    .stat {
      padding: 20px;
      border: 1px solid rgba(35, 33, 31, 0.08);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.48);
    }

    .stat strong {
      display: block;
      margin-bottom: 4px;
      font-size: 1.8rem;
      letter-spacing: -0.06em;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 650;
    }

    .hero-feature {
      display: grid;
      gap: 18px;
    }

    .look-card,
