      --muted: #686b72;
      --line: #e8e5df;
      --paper: #fbfaf7;
      --card: #ffffff;
      --charcoal: #23211f;
      --sage: #dce8d6;
      --sand: #efe4d2;
      --clay: #b96f51;
      --lime: #dff26d;
      --shadow: 0 24px 70px rgba(28, 26, 23, 0.12);
      --radius-xl: 34px;
      --radius-lg: 24px;
      --radius-md: 16px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      background:
        radial-gradient(circle at top left, rgba(223, 242, 109, 0.28), transparent 30rem),
        linear-gradient(180deg, #fbfaf7 0%, #f5f0e8 100%);
      color: var(--ink);
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      border: 0;
      font: inherit;
      cursor: pointer;
    }

    .app {
      min-height: 100vh;
      overflow: hidden;
    }

    .container {
      width: min(1180px, calc(100% - 40px));
      margin: 0 auto;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(18px);
      background: rgba(251, 250, 247, 0.78);
      border-bottom: 1px solid rgba(232, 229, 223, 0.8);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 22px;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      letter-spacing: -0.04em;
      font-size: 1.2rem;
    }

    .brand-mark {
      display: grid;
      place-items: center;
      width: 38px;
      height: 38px;
      border-radius: 14px;
      color: var(--paper);
      background: var(--charcoal);
      box-shadow: 0 10px 25px rgba(35, 33, 31, 0.18);
    }

    .nav-links {
      display: flex;
      gap: 26px;
      color: var(--muted);
      font-size: 0.95rem;
      font-weight: 650;
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .pill {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-height: 44px;
      padding: 0 18px;
      border-radius: 999px;
      font-weight: 750;
      transition: transform 180ms ease, box-shadow 180ms ease, background 180ms ease;
    }

    .pill:hover {
      transform: translateY(-2px);
    }

    .pill-dark {
      background: var(--charcoal);
      color: white;
      box-shadow: 0 16px 35px rgba(35, 33, 31, 0.18);
    }

    .pill-light {
      background: white;
      color: var(--charcoal);
      border: 1px solid var(--line);
    }

    .hero {
      padding: 54px 0 34px;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(340px, 0.82fr);
      gap: 28px;
      align-items: stretch;
    }

    .hero-copy {
      position: relative;
      min-height: 610px;
      padding: 58px;
      border-radius: var(--radius-xl);
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.74), rgba(255, 255, 255, 0.36)),
        var(--sand);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .hero-copy::after {
      content: "";
      position: absolute;
      width: 360px;
      height: 360px;
      right: -90px;
      bottom: -100px;
      border-radius: 50%;
      background: rgba(220, 232, 214, 0.8);
      filter: blur(4px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      width: fit-content;
      margin: 0 0 22px;
      padding: 8px 12px;
      border: 1px solid rgba(35, 33, 31, 0.1);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.58);
      color: #5d5a54;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .eyebrow::before {
      content: "";
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--clay);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    h1,
    h2,
    h3,
    p {
      margin-top: 0;
    }

    h1 {
      position: relative;
      z-index: 1;
      max-width: 780px;
      margin-bottom: 22px;
      font-size: clamp(3.2rem, 8vw, 7.35rem);
      line-height: 0.9;
      letter-spacing: -0.09em;
    }

    .hero-copy > p {
      position: relative;
      z-index: 1;
      max-width: 550px;
      margin-bottom: 34px;
      color: #54504a;
      font-size: clamp(1.04rem, 2vw, 1.25rem);
      line-height: 1.65;
    }

    .hero-actions {
      position: relative;
      z-index: 1;
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-bottom: 56px;
    }

    .hero-stats {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
      max-width: 640px;
    }

    .stat {
      padding: 20px;
      border: 1px solid rgba(35, 33, 31, 0.08);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.48);
    }

    .stat strong {
      display: block;
      margin-bottom: 4px;
      font-size: 1.8rem;
      letter-spacing: -0.06em;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.9rem;
      font-weight: 650;
    }

    .hero-feature {
      display: grid;
      gap: 18px;
    }

    .look-card,
    .mini-deal {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow);
    }

    .look-card {
      min-height: 430px;
      padding: 28px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      background:
        linear-gradient(180deg, rgba(20, 20, 20, 0.03), rgba(20, 20, 20, 0.62)),
        url("https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=1200&q=80") center/cover;
      color: white;
    }

    .floating-badge {
      align-self: flex-start;
      padding: 9px 13px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.86);
      color: var(--charcoal);
      font-size: 0.76rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .look-card h2 {
      margin-bottom: 10px;
      font-size: 2.25rem;
      line-height: 1;
      letter-spacing: -0.06em;
    }

    .look-card p {
      max-width: 330px;
      margin-bottom: 0;
      color: rgba(255, 255, 255, 0.82);
      line-height: 1.55;
    }

    .mini-deal {
      display: grid;
      grid-template-columns: 1fr 150px;
      min-height: 164px;
      background: var(--charcoal);
      color: white;
    }

    .mini-deal-copy {
      padding: 26px;
    }

    .mini-deal strong {
      display: block;
      margin-bottom: 7px;
      color: var(--lime);
      font-size: 0.84rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .mini-deal h3 {
      margin-bottom: 12px;
      font-size: 1.7rem;
      line-height: 1.03;
      letter-spacing: -0.05em;
    }

    .mini-deal a {
      color: rgba(255, 255, 255, 0.74);
      font-weight: 800;
    }

    .mini-deal-art {
      background:
        radial-gradient(circle at 30% 25%, #f7c57d 0 16%, transparent 17%),
        radial-gradient(circle at 68% 42%, #dff26d 0 13%, transparent 14%),
        radial-gradient(circle at 52% 78%, #d69b86 0 18%, transparent 19%),
        #35322d;
    }

    section {
      padding: 54px 0;
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 24px;
    }

    .section-heading h2 {
      margin-bottom: 0;
      font-size: clamp(2.1rem, 5vw, 4.3rem);
      line-height: 0.95;
      letter-spacing: -0.08em;
    }

    .section-heading p {
      max-width: 430px;
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 18px;
    }

    .product-card {
      padding: 12px;
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.72);
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 22px 55px rgba(31, 28, 25, 0.1);
    }

    .product-media {
      position: relative;
      display: grid;
      place-items: center;
      min-height: 270px;
      border-radius: 18px;
      overflow: hidden;
      background: var(--product-bg);
    }

    .product-media img {
      width: 100%;
      height: 270px;
      object-fit: cover;
      mix-blend-mode: multiply;
      filter: saturate(0.92) contrast(0.98);
    }

    .tag {
      position: absolute;
      top: 14px;
      left: 14px;
      padding: 7px 10px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.78);
      color: #494540;
      font-size: 0.72rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .quick-add {
      position: absolute;
      right: 14px;
      bottom: 14px;
      width: 42px;
      height: 42px;
      border-radius: 50%;
      background: var(--charcoal);
      color: white;
      font-size: 1.35rem;
      box-shadow: 0 12px 28px rgba(20, 20, 20, 0.18);
    }

    .product-info {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 14px;
      padding: 18px 4px 4px;
    }

    .product-info h3 {
      margin-bottom: 6px;
      font-size: 1.03rem;
      letter-spacing: -0.03em;
    }

    .product-info p {
      margin-bottom: 0;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .price {
      font-weight: 850;
      white-space: nowrap;
    }

    .deals-board {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 18px;
    }

    .deal-hero,
    .deal-stack article {
      border-radius: var(--radius-xl);
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.45);
      box-shadow: var(--shadow);
    }

    .deal-hero {
      min-height: 430px;
      padding: 40px;
      background:
        linear-gradient(110deg, rgba(35, 33, 31, 0.9), rgba(35, 33, 31, 0.42)),
        url("https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=80") center/cover;
      color: white;
    }

    .deal-hero .eyebrow {
      background: rgba(255, 255, 255, 0.15);
      color: rgba(255, 255, 255, 0.82);
      border-color: rgba(255, 255, 255, 0.16);
    }

    .deal-hero h2 {
      max-width: 550px;
      margin-bottom: 18px;
      font-size: clamp(2.4rem, 5vw, 5.6rem);
      line-height: 0.92;
      letter-spacing: -0.08em;
    }

    .deal-hero p {
      max-width: 430px;
      margin-bottom: 28px;
      color: rgba(255, 255, 255, 0.78);
      line-height: 1.6;
    }

    .deal-stack {
      display: grid;
      gap: 18px;
    }

    .deal-stack article {
      min-height: 206px;
      padding: 28px;
      background: var(--card);
    }

    .deal-stack article:first-child {
      background: var(--sage);
    }

    .deal-stack article:last-child {
      background: #f4d9cf;
    }

    .deal-stack span {
      display: inline-block;
      margin-bottom: 42px;
      color: rgba(35, 33, 31, 0.6);
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    .deal-stack h3 {
      max-width: 370px;
      margin-bottom: 8px;
      font-size: 2rem;
      line-height: 1;
      letter-spacing: -0.06em;
    }

    .deal-stack p {
      margin-bottom: 0;
      color: #615c55;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 18px;
    }

    .story-card {
      min-height: 490px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 18px;
      border-radius: var(--radius-xl);
      background: var(--card);
      border: 1px solid var(--line);
    }

    .story-card.featured {
      grid-column: span 2;
      background:
        linear-gradient(180deg, transparent, rgba(20, 20, 20, 0.72)),
        url("https://images.unsplash.com/photo-1511556820780-d912e42b4980?auto=format&fit=crop&w=1200&q=80") center/cover;
      color: white;
      border: 0;
    }

    .story-image {
      height: 250px;
      border-radius: 20px;
      object-fit: cover;
      width: 100%;
    }

    .story-meta {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 16px;
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .featured .story-meta {
      color: rgba(255, 255, 255, 0.72);
    }

    .story-card h3 {
      margin-bottom: 12px;
      font-size: clamp(1.7rem, 3vw, 3rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
    }

    .story-card p {
      margin-bottom: 0;
      color: var(--muted);
      line-height: 1.55;
    }

    .featured p {
      max-width: 540px;
      color: rgba(255, 255, 255, 0.78);
    }

    .newsletter {
      padding-bottom: 76px;
    }

    .newsletter-card {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 24px;
      align-items: center;
      padding: 38px;
      border-radius: var(--radius-xl);
      background: var(--charcoal);
      color: white;
      box-shadow: var(--shadow);
    }

    .newsletter-card h2 {
      margin-bottom: 8px;
      font-size: clamp(2rem, 4vw, 3.8rem);
      line-height: 0.95;
      letter-spacing: -0.08em;
    }

    .newsletter-card p {
      margin-bottom: 0;
      color: rgba(255, 255, 255, 0.68);
    }

    .signup {
      display: flex;
      gap: 8px;
      padding: 8px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.1);
    }

    .signup input {
      width: min(330px, 40vw);
      border: 0;
      outline: 0;
      padding: 0 18px;
      background: transparent;
      color: white;
      font: inherit;
    }

    .signup input::placeholder {
      color: rgba(255, 255, 255, 0.48);
    }

    footer {
      padding: 30px 0 42px;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .footer-row {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      border-top: 1px solid var(--line);
      padding-top: 24px;
    }

    @media (max-width: 980px) {
      .hero-grid,
      .deals-board,
      .newsletter-card {
        grid-template-columns: 1fr;
      }

      .hero-copy {
        min-height: auto;
      }

      .product-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .story-card.featured {
        grid-column: span 2;
      }

      .signup input {
        width: 100%;
      }
    }

    @media (max-width: 720px) {
      .container {
        width: min(100% - 28px, 1180px);
      }

      .nav {
        min-height: auto;
        padding: 16px 0;
      }

      .nav-links,
      .nav-actions .pill-light {
        display: none;
      }

      .hero {
        padding-top: 24px;
      }

      .hero-copy,
      .deal-hero,
      .newsletter-card {
        padding: 28px;
        border-radius: 26px;
      }

      .hero-stats,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .mini-deal {
        grid-template-columns: 1fr;
      }

      .mini-deal-art {
        min-height: 92px;
      }

      .section-heading,
      .footer-row {
        align-items: start;
        flex-direction: column;
      }

      .story-card.featured {
        grid-column: auto;
      }

      .signup {
        align-items: stretch;
        flex-direction: column;
        border-radius: 24px;
      }

      .signup input {
        min-height: 48px;
      }
    }
  </style>
</head>
<body>
  <div id="root" class="app"></div>

  <script>
    const featuredProducts = [
      {
        name: "Transit Weekender",
        category: "Travel bags",
        price: "$148",
        tag: "New",
        image: "https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=900&q=80",
        bg: "#e9e2d6"
      },
      {
