        bg: "#ece8d8"
      }
    ];

    const editorialStories = [
      {
        title: "The reset guide: five pieces that make weekdays easier",
        category: "Editorial",
        readTime: "6 min read",
        copy: "Our stylists build a calm, functional capsule around texture, utility, and seasonless color."
      },
      {
        title: "Inside the makers' studio",
        category: "Craft",
        readTime: "4 min read",
        copy: "Meet the small-batch partners behind our ceramics, canvas accessories, and naturally dyed staples.",
        image: "https://images.unsplash.com/photo-1494438639946-1ebd1d20bf85?auto=format&fit=crop&w=900&q=80"
      }
    ];

    function Header() {
      return `
        <header class="site-header">
          <nav class="container nav" aria-label="Main navigation">
            <a class="brand" href="#">
              <span class="brand-mark">N</span>
              Northline
            </a>
            <div class="nav-links">
              <a href="#featured">Featured</a>
              <a href="#deals">Deals</a>
              <a href="#journal">Journal</a>
              <a href="#newsletter">Members</a>
            </div>
            <div class="nav-actions">
              <a class="pill pill-light" href="#">Search</a>
              <a class="pill pill-dark" href="#">Bag 02</a>
            </div>
          </nav>
        </header>
      `;
    }

    function Hero() {
      return `
        <section class="hero">
          <div class="container hero-grid">
            <div class="hero-copy">
              <span class="eyebrow">Spring edit is live</span>
              <h1>Retail staples for a better daily rhythm.</h1>
              <p>Discover modern home, style, and travel essentials selected for quality, comfort, and a lighter footprint.</p>
              <div class="hero-actions">
                <a class="pill pill-dark" href="#featured">Shop the edit</a>
                <a class="pill pill-light" href="#journal">Read the journal</a>
              </div>
              <div class="hero-stats" aria-label="Store highlights">
                <div class="stat"><strong>240+</strong><span>new arrivals</span></div>
                <div class="stat"><strong>48h</strong><span>member shipping</span></div>
                <div class="stat"><strong>4.9</strong><span>average rating</span></div>
              </div>
            </div>
            <aside class="hero-feature" aria-label="Featured collection">
              <article class="look-card">
                <span class="floating-badge">Curated look</span>
                <div>
                  <h2>Warm neutrals, sharp utility.</h2>
                  <p>A complete shelf-to-street assortment built for compact living and easy packing.</p>
