                <div class="mini-deal-art" aria-hidden="true"></div>
              </article>
            </aside>
          </div>
        </section>
      `;
    }

    function ProductCard(product) {
      return `
        <article class="product-card">
          <div class="product-media" style="--product-bg: ${product.bg}">
            <span class="tag">${product.tag}</span>
            <img src="${product.image}" alt="${product.name}">
            <button class="quick-add" aria-label="Add ${product.name} to bag">+</button>
          </div>
          <div class="product-info">
            <div>
              <h3>${product.name}</h3>
              <p>${product.category}</p>
            </div>
            <span class="price">${product.price}</span>
          </div>
        </article>
      `;
    }

    function FeaturedProducts() {
      return `
        <section id="featured" class="featured-products">
          <div class="container">
            <div class="section-heading">
              <h2>Featured products</h2>
              <p>Customer favorites and fresh arrivals chosen for versatility, premium materials, and polished everyday use.</p>
            </div>
            <div class="product-grid">
